// The installation id (build contract §4): a stable id per app installation, generated by
// the SDK and persisted by the app. Messaging keys the partner session device by it,
// Calling the endpoint (`inst:<installationId>`), push registrations the device handle.
//
// Storage is pluggable through the `getItem` / `setItem` shape shared by the browser's
// `localStorage` and React Native's AsyncStorage (sync or async), so no storage library is
// a dependency. The default is in memory (a new id per process: fine on servers and in
// tests, NOT on devices).

import { CfMeetConfigurationError } from './errors.js';

/** `[A-Za-z0-9._-]{8,128}`. */
export const INSTALLATION_ID_RE = /^[A-Za-z0-9._-]{8,128}$/;
/** The storage key the SDK uses by default. */
export const DEFAULT_INSTALLATION_ID_KEY = 'cfmeet.installationId';

/** Key-value storage: `localStorage`, React Native AsyncStorage, or your own. */
export interface KeyValueStorage {
  getItem(key: string): string | null | undefined | Promise<string | null | undefined>;
  setItem(key: string, value: string): void | Promise<void>;
}

export function isValidInstallationId(id: unknown): id is string {
  return typeof id === 'string' && INSTALLATION_ID_RE.test(id);
}

/** A new random installation id (`inst-` + 32 hex characters from Web Crypto). */
export function generateInstallationId(): string {
  const c = (globalThis as { crypto?: Crypto }).crypto;
  if (!c || typeof c.getRandomValues !== 'function') {
    throw new CfMeetConfigurationError('no Web Crypto in this runtime: pass an installationId explicitly');
  }
  const b = c.getRandomValues(new Uint8Array(16));
  return `inst-${Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('')}`;
}

/** In-memory storage (the default). */
export function createMemoryStorage(initial: Record<string, string> = {}): KeyValueStorage & { readonly values: Map<string, string> } {
  const values = new Map(Object.entries(initial));
  return {
    values,
    getItem: (k) => values.get(k) ?? null,
    setItem: (k, v) => void values.set(k, v),
  };
}

/** The browser's `localStorage` (null when unavailable, e.g. on servers or in private modes that throw). */
export function browserLocalStorage(): KeyValueStorage | null {
  try {
    const s = (globalThis as { localStorage?: KeyValueStorage }).localStorage;
    return s && typeof s.getItem === 'function' && typeof s.setItem === 'function' ? s : null;
  } catch {
    return null;
  }
}

export interface InstallationIdStoreOptions {
  /** Where the id persists (default in memory). */
  readonly storage?: KeyValueStorage;
  /** Storage key (default `cfmeet.installationId`). */
  readonly key?: string;
}

/** Reads the persisted installation id, creating and saving one on first use. */
export class InstallationIdStore {
  readonly #storage: KeyValueStorage;
  readonly #key: string;
  #pending: Promise<string> | null = null;

  constructor(options: InstallationIdStoreOptions = {}) {
    this.#storage = options.storage ?? createMemoryStorage();
    this.#key = options.key ?? DEFAULT_INSTALLATION_ID_KEY;
    if (typeof this.#storage.getItem !== 'function' || typeof this.#storage.setItem !== 'function') {
      throw new CfMeetConfigurationError('installation id storage must have getItem and setItem');
    }
  }

  /** The installation id (concurrent callers share one read / write). */
  get(): Promise<string> {
    if (!this.#pending) {
      this.#pending = this.#load();
      this.#pending.catch(() => (this.#pending = null));
    }
    return this.#pending;
  }

  /** Forgets the id (e.g. on sign-out when the app wants a new device identity). */
  async reset(): Promise<string> {
    const id = generateInstallationId();
    await this.#storage.setItem(this.#key, id);
    this.#pending = Promise.resolve(id);
    return id;
  }

  async #load(): Promise<string> {
    const stored = await this.#storage.getItem(this.#key);
    if (isValidInstallationId(stored)) return stored;
    const id = generateInstallationId();
    await this.#storage.setItem(this.#key, id);
    return id;
  }
}
